<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\{Role,User};
use Illuminate\Http\Request;
class UserController extends Controller { private function allow(){abort_unless(auth()->user()->can('manage-users'),403);} public function index(){ $this->allow();return view('admin.users.index',['items'=>User::with('role')->latest()->paginate(20)]);} public function create(){ $this->allow();return view('admin.users.form',['item'=>new User,'roles'=>Role::all()]);} public function store(Request $r){$this->allow();$d=$r->validate(['role_id'=>'required|exists:roles,id','name'=>'required|string|max:255','email'=>'required|email|unique:users,email','password'=>'required|confirmed|min:8','is_active'=>'nullable|boolean']);User::create($d+['is_active'=>(bool)($d['is_active']??false)]);return redirect()->route('admin.users.index')->with('success','Pengguna ditambahkan.');} public function edit(User $user){$this->allow();return view('admin.users.form',['item'=>$user,'roles'=>Role::all()]);} public function update(Request $r,User $user){$this->allow();$d=$r->validate(['role_id'=>'required|exists:roles,id','name'=>'required|string|max:255','email'=>'required|email|unique:users,email,'.$user->id,'password'=>'nullable|confirmed|min:8','is_active'=>'nullable|boolean']);if(empty($d['password']))unset($d['password']);$d['is_active']=(bool)($d['is_active']??false);abort_if($user->is(auth()->user())&&!$d['is_active'],422,'Tidak dapat menonaktifkan akun sendiri.');$user->update($d);return back()->with('success','Pengguna diperbarui.');} }
